    internal static string Name(CompletionItemKind kind) => kind switch
    {
        // Upstream deliberately aliases method/function/constructor; do not invent differing glyphs.
        CompletionItemKind.Method or CompletionItemKind.Function or CompletionItemKind.Constructor => "method",
        CompletionItemKind.Field => "field", CompletionItemKind.Variable => "variable",
        CompletionItemKind.Class => "class", CompletionItemKind.Struct => "structure",
        CompletionItemKind.Interface => "interface", CompletionItemKind.Module => "namespace",
        CompletionItemKind.Property => "property", CompletionItemKind.Event => "event",
        CompletionItemKind.Operator => "operator", CompletionItemKind.Unit => "ruler",
        CompletionItemKind.Value or CompletionItemKind.Enum => "enum", CompletionItemKind.Constant => "constant",
        CompletionItemKind.EnumMember => "enum-member", CompletionItemKind.Keyword => "keyword",
        CompletionItemKind.Color or CompletionItemKind.CustomColor => "color", CompletionItemKind.File => "file",
        CompletionItemKind.Reference => "reference", CompletionItemKind.Folder => "folder",
        CompletionItemKind.TypeParameter => "parameter", CompletionItemKind.User => "account",
        CompletionItemKind.Issue => "issues", CompletionItemKind.Snippet => "snippet", _ => "key",
    };
    internal static FrameworkElement Create(CompletionItemKind kind, Brush brush)
    {
        var canvas = new Canvas { Width = 16, Height = 16, VerticalAlignment = VerticalAlignment.Center,
            HorizontalAlignment = HorizontalAlignment.Center, IsHitTestVisible = false };
        foreach (var data in Paths[Name(kind)])
        {
            // Data is a fixed, bundled path table, never server-supplied XAML.
            var path = (Microsoft.UI.Xaml.Shapes.Path)XamlReader.Load(
                "<Path xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' Data='" + data + "' />");
            path.Fill = brush;
            canvas.Children.Add(path);
        }
        return canvas;
    }
